    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k,v in e.items():
                if k.startswith('value'): return v
    return None
pats={p['id']:p for p in E['Patient']}
spec={s['id']:s for s in E['Specimen']}
acc=collections.defaultdict(list)
for b in E['Basic']:
    acc[ext(b,'accession')].append(b)
def sub(r):
    for k in ('subject','patient','for'):
