        elif t=='Observation':
            sp=r.get('specimen',{}).get('reference','').split('/')[-1]
            s=spec.get(sp)
            a=(r.get('identifier') or [{}])[0].get('value')
            print(f"  [{et}] Observation {rid} {r['code']['text']} status={r['status']} coll={r.get('effectiveDateTime')} issued={r.get('issued')} value={r.get('valueString')!r} acc={a}",file=out)
            if r.get('note'): print(f"          note: {[n['text'] for n in r['note']]}",file=out)
            if s:
                print(f"          Specimen {s['id']} accession={s.get('accessionIdentifier',{}).get('value')} collected={s['collection'].get('collectedDateTime')} collector={s['collection'].get('collector',{}).get('display')} label={ext(s,'label-name')}|{ext(s,'label-mrn')}|{ext(s,'label-dob')} subject={sub(s)}",file=out)
