            else:
                print(f"          (no specimen ref)",file=out)
                for b in acc.get(a,[]):
                    print(f"          Accessioning {b['id']} acc={ext(b,'accession')} name={ext(b,'patient-name')} mrn={ext(b,'patient-mrn')} dob={ext(b,'patient-dob')}",file=out)
        elif t=='Specimen':
            print(f"  [{et}] Specimen {rid} accession={r.get('accessionIdentifier',{}).get('value')} collected={r['collection'].get('collectedDateTime')} label={ext(r,'label-name')}|{ext(r,'label-mrn')}|{ext(r,'label-dob')}",file=out)
        elif t=='MedicationAdministration':
            print(f"  [{et}] MedAdmin {rid} status={r['status']} when={r.get('effectiveDateTime')} dose={r.get('dosage',{}).get('text')} performer={[x.get('actor',{}).get('display') for x in r.get('performer',[])]} med={r.get('medicationCodeableConcept',{}).get('text')}",file=out)
            if r.get('note'): print(f"          note: {[n['text'] for n in r['note']]}",file=out)
            if r.get('statusReason'): print(f"          statusReason: {r['statusReason']}",file=out)
        elif t=='MedicationDispense':
            print(f"  [{et}] MedDispense {rid} med={r.get('medicationCodeableConcept',{}).get('text')} qty={r.get('quantity')} daysSupply={r.get('daysSupply')} handed={r.get('whenHandedOver')} dosage={[d.get('text') for d in r.get('dosageInstruction',[])]}",file=out)
            if r.get('note'): print(f"          note: {[n['text'] for n in r['note']]}",file=out)
        elif t=='DocumentReference':
            print(f"  [{et}] Document {rid} type={r.get('type',{}).get('text')} date={r.get('date')} author={[a.get('display') for a in r.get('author',[])]} role={ext(r,'author-role')}",file=out)
            print(f"          TEXT: {r.get('description')}",file=out)
        elif t=='AllergyIntolerance':
            print(f"  [{et}] Allergy {rid} {r.get('code',{}).get('text')} reaction={json.dumps(r.get('reaction'))}",file=out)
        elif t=='Task':
            print(f"  [{et}] Task {rid} status={r['status']} code={r.get('code',{}).get('coding',[{}])[0].get('code')} focus={r.get('focus',{}).get('reference')} desc={r.get('description')}",file=out)
        else:
            print(f"  [{et}] {t} {rid} {json.dumps(r)[:300]}",file=out)
out.close()
# orphan observations without patient subject? and specimens not referenced
refd={o.get('specimen',{}).get('reference','').split('/')[-1] for o in E['Observation']}
print("specimens not referenced by any obs:",[s['id'] for s in E['Specimen'] if s['id'] not in refd])
